  ('pagibig-2024', 'employer.pagibig', 'employer_contributions', 'all', '{"employee_rate":"0.02","employee_rate_low":"0.01","low_income_limit":"1500","employer_rate":"0.02","max_compensation":"10000"}'::jsonb, '2024-02-01', null, 'RA 9679 Sec. 7; HDMF circular raising the maximum fund salary to ₱10,000 (number to confirm)', 'https://www.pagibigfund.gov.ph/', null, true, 'To confirm: ₱10,000 maximum monthly compensation (₱200 maximum each from employee and employer).'),
  ('thirteenth-month-pd851', 'employer.thirteenth_month', 'employer_contributions', 'all', '{"fraction_of_basic_salary":"0.0833333333","pay_by_month":12,"pay_by_day":24}'::jsonb, '1975-12-16', null, 'PD 851 (13th Month Pay Law) and its implementing rules: 1/12 of the total basic salary earned within the calendar year, paid on or before 24 December', 'https://www.dole.gov.ph/', null, true, 'To confirm: coverage (rank-and-file employees) and exemptions under the implementing rules.'),
  ('books-retention', 'bookkeeping.retention_years', 'bookkeeping', 'all', '{"years":5}'::jsonb, '2018-01-01', null, 'NIRC Sec. 235, as amended (preservation of books of accounts and records)', 'https://www.bir.gov.ph/', null, true, 'LOW CONFIDENCE: retention period and when it starts to run (to confirm, including any change under RA 11976).'),
  ('books-audit-threshold-train', 'bookkeeping.audit_threshold', 'bookkeeping', 'all', '{"quarterly_gross_over":"3000000"}'::jsonb, '2018-01-01', null, 'NIRC Sec. 232(A), as amended by RA 10963 (TRAIN): books audited by an independent CPA when gross quarterly sales, earnings, receipts or output exceed the threshold', 'https://www.bir.gov.ph/', null, true, 'To confirm: the ₱3,000,000 threshold, whether it is per quarter, and how it applies to corporations (which attach audited statements under other rules).'),
  ('lgu-permit-renewal', 'lgu.permit_renewal', 'lgu', 'all', '{"month":1,"by_day":20}'::jsonb, '1992-01-01', null, 'RA 7160 (Local Government Code) Secs. 165 and 167: renewal and payment within the first 20 days of January', null, null, true, 'To confirm: LGUs may extend the deadline by ordinance.'),
  ('lgu-business-tax-payment', 'lgu.business_tax_payment', 'lgu', 'all', '{"options":["annual","quarterly"],"quarterly_due_within_days":20}'::jsonb, '1992-01-01', null, 'RA 7160 Sec. 165: local taxes may be paid annually or in quarterly installments within the first 20 days of each quarter', null, null, true, 'To confirm: installment rules and surcharges are set by each LGU''s revenue code.')
insert into public.forms (code, name, description, who_files, frequency, filing_channels, guide_slug, needs_verification) values
  ('1701Q', 'Quarterly Income Tax Return for Individuals, Estates and Trusts', 'Reports income and pays income tax for the first three quarters of the year.', 'Self-employed individuals, professionals, sole proprietors and mixed-income earners.', 'quarterly', array['eBIRForms', 'eFPS']::text[], '1701q', true),
  ('1701', 'Annual Income Tax Return for Individuals (including Mixed-Income), Estates and Trusts', 'Annual return for mixed-income earners and for individuals using itemized deductions.', 'Mixed-income earners; self-employed individuals using itemized deductions; estates and trusts.', 'annual', array['eBIRForms', 'eFPS']::text[], '1701', true),
  ('1701A', 'Annual Income Tax Return for Individuals Earning Income Purely from Business/Profession', 'Simplified annual return for those on the 8% option or graduated rates with OSD.', 'Purely self-employed individuals and professionals using the 8% rate or OSD.', 'annual', array['eBIRForms', 'eFPS']::text[], '1701a', true),
  ('2551Q', 'Quarterly Percentage Tax Return', 'Reports gross sales/receipts and pays percentage tax for non-VAT taxpayers.', 'Non-VAT-registered persons not on the 8% income tax option, and others subject to percentage tax.', 'quarterly', array['eBIRForms', 'eFPS']::text[], '2551q', true),
  ('2550Q', 'Quarterly Value-Added Tax Return', 'Reports output VAT less input VAT for the quarter.', 'VAT-registered persons.', 'quarterly', array['eBIRForms', 'eFPS']::text[], '2550q', true),
  ('1601C', 'Monthly Remittance Return of Income Taxes Withheld on Compensation', 'Remits tax withheld from employees'' salaries for the month.', 'Employers (withholding agents) with employees.', 'monthly', array['eBIRForms', 'eFPS']::text[], '1601c', true),
  ('0619E', 'Monthly Remittance Form of Creditable Income Taxes Withheld (Expanded)', 'Remits expanded withholding tax for the first two months of each quarter.', 'Withholding agents paying income subject to expanded withholding (e.g. rent, professional fees, contractors).', 'monthly', array['eBIRForms', 'eFPS']::text[], '0619e', true),
  ('1601EQ', 'Quarterly Remittance Return of Creditable Income Taxes Withheld (Expanded)', 'Quarterly summary and remittance of expanded withholding tax, with the QAP attachment.', 'Withholding agents for expanded withholding tax.', 'quarterly', array['eBIRForms', 'eFPS']::text[], '1601eq', true),
  ('1604C', 'Annual Information Return of Income Taxes Withheld on Compensation', 'Annual summary of compensation paid and taxes withheld, with the alphalist of employees.', 'Employers (withholding agents) with employees.', 'annual', array['eBIRForms', 'eFPS']::text[], '1604c', true),
  ('1604E', 'Annual Information Return of Creditable Income Taxes Withheld (Expanded)', 'Annual summary of expanded withholding, with the alphalist of payees.', 'Withholding agents for expanded withholding tax.', 'annual', array['eBIRForms', 'eFPS']::text[], '1604e', true),
  ('1702Q', 'Quarterly Income Tax Return for Corporations, Partnerships and Other Non-Individual Taxpayers', 'Quarterly corporate income tax return.', 'Corporations, partnerships, OPCs and other non-individual taxpayers.', 'quarterly', array['eBIRForms', 'eFPS']::text[], '1702q', true),
  ('1702-RT', 'Annual Income Tax Return for Corporations, Partnerships and Other Non-Individual Taxpayers Subject Only to the Regular Income Tax Rate', 'Annual corporate income tax return at the regular rate.', 'Corporations and partnerships subject to the regular rate.', 'annual', array['eBIRForms', 'eFPS']::text[], '1702-rt', true),
  ('1901', 'Application for Registration for Self-Employed (Single Proprietor/Professional), Mixed-Income Individuals, Non-Resident Alien Engaged in Trade/Business, Estate and Trust', 'BIR registration form for individuals with business income.', 'Sole proprietors, professionals and mixed-income earners registering with BIR.', 'one_time', array['ORUS', 'manual']::text[], null, true),
  ('1903', 'Application for Registration for Corporations/Partnerships (Taxable/Non-Taxable)', 'BIR registration form for juridical entities.', 'Corporations, partnerships, OPCs, cooperatives.', 'one_time', array['ORUS', 'manual']::text[], null, true),
  ('1706', 'Capital Gains Tax Return for Onerous Transfer of Real Property Classified as Capital Assets', 'Capital gains tax on the sale of real property held as a capital asset.', 'Sellers of real property held as a capital asset (not used in business).', 'one_time', array['eBIRForms', 'manual']::text[], '1706', true),
  ('1707', 'Capital Gains Tax Return for Onerous Transfer of Shares of Stock Not Traded Through the Local Stock Exchange', 'Capital gains tax on the sale of shares not listed or not traded on the stock exchange.', 'Sellers of unlisted shares of stock.', 'one_time', array['eBIRForms', 'manual']::text[], '1707', true),
  ('1800', 'Donor''s Tax Return', 'Donor''s tax on gifts of money or property.', 'Donors (individuals or entities) making gifts.', 'one_time', array['eBIRForms', 'manual']::text[], '1800', true),
  ('1801', 'Estate Tax Return', 'Estate tax on the net estate of a person who has died.', 'The executor, administrator or heirs of the decedent.', 'one_time', array['eBIRForms', 'manual']::text[], '1801', true),
  ('2000-OT', 'Documentary Stamp Tax Declaration/Return (One-Time Transactions)', 'Documentary stamp tax on one-time transactions such as the sale of real property.', 'Parties to one-time taxable documents, such as the seller or buyer in a sale of real property.', 'one_time', array['eBIRForms', 'manual']::text[], '2000-ot', true),
  ('1905', 'Application for Registration Information Update/Correction/Cancellation', 'Updates or cancels a BIR registration: transfer of RDO, new tax types, closure of business.', 'Registered taxpayers changing their registration details or closing their business.', 'one_time', array['ORUS', 'manual']::text[], '1905', true),
  ('1700', 'Annual Income Tax Return for Individuals Earning Purely Compensation Income', 'Annual income tax return for employees not covered by substituted filing.', 'Employees with purely compensation income who do not qualify for substituted filing, such as those with two or more employers in the year.', 'annual', array['eBIRForms', 'manual']::text[], '1700', true),
  ('1702-EX', 'Annual Income Tax Return for Corporations, Partnerships and Other Non-Individuals Exempt from Income Tax', 'Annual return for organizations whose income is exempt under the Tax Code or special laws.', 'Exempt corporations and organizations, such as qualified non-stock, non-profit organizations, with no taxable income.', 'annual', array['eBIRForms', 'eFPS']::text[], '1702-ex', true),
  ('1702-MX', 'Annual Income Tax Return for Corporations, Partnerships and Other Non-Individuals with Mixed Income Subject to Multiple Rates', 'Annual return for corporations with income under the regular rate and a special rate or exemption.', 'Corporations with mixed income, such as registered business enterprises with both incentive and regular income.', 'annual', array['eBIRForms', 'eFPS']::text[], '1702-mx', true),
  ('2000', 'Monthly Documentary Stamp Tax Declaration/Return', 'Documentary stamp tax on documents such as loans, shares of stock, leases and insurance policies, reported monthly.', 'Persons who make, sign, issue, accept or transfer documents subject to documentary stamp tax.', 'monthly', array['eBIRForms', 'eFPS']::text[], '2000', true),
  ('1906', 'Application for Authority to Print Invoices', 'Application for the BIR''s authority before a printer prints your invoices.', 'Businesses before printing a new batch of invoices.', 'one_time', array['ORUS', 'manual']::text[], '1906', true)
insert into public.deadline_rules (id, form_code, title, frequency, due_logic_json, applies_when_json, filing_channel, effective_from, effective_to, legal_basis, source_url, last_verified_at, needs_verification, note) values
  ('dl-1701q', '1701Q', 'Quarterly income tax return (individuals)', 'quarterly', '{"kind":"quarterly","quarter_basis":"calendar","quarters":[1,2,3],"month_offset":2,"day":15}'::jsonb, '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship"]}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 74(A), as amended by RA 10963 (TRAIN): 15 May, 15 Aug, 15 Nov', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1701a', '1701A', 'Annual income tax return (purely business/profession, 8% or OSD)', 'annual', '{"kind":"annual","year_basis":"calendar","month_offset":4,"day":15}'::jsonb, '{"taxpayer_types":["self_employed","sole_proprietorship"],"income_tax_options":["eight_percent","graduated_osd"]}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 51(C)(1); RR 8-2018; RMC 37-2019 (1701A)', 'https://www.bir.gov.ph/', null, true, 'RMC number for the 1701A form version to confirm.'),
  ('dl-1701', '1701', 'Annual income tax return (mixed income or itemized deductions)', 'annual', '{"kind":"annual","year_basis":"calendar","month_offset":4,"day":15}'::jsonb, '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship"],"not":{"taxpayer_types":["self_employed","sole_proprietorship"],"income_tax_options":["eight_percent","graduated_osd"]}}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 51(C)(1): on or before 15 April of the following year', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-2551q', '2551Q', 'Quarterly percentage tax return', 'quarterly', '{"kind":"quarterly","quarter_basis":"taxable_year","quarters":[1,2,3,4],"days_after":25}'::jsonb, '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"],"vat_status":["non_vat"],"not":{"income_tax_options":["eight_percent"]}}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 128(A)(1), as amended by RA 10963 (TRAIN): within 25 days after the end of each taxable quarter', 'https://www.bir.gov.ph/', null, true, '8% income tax option is in lieu of percentage tax. Cooperatives may be exempt under RA 9520 — to confirm.'),
  ('dl-2550q', '2550Q', 'Quarterly VAT return', 'quarterly', '{"kind":"quarterly","quarter_basis":"taxable_year","quarters":[1,2,3,4],"days_after":25}'::jsonb, '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"],"vat_status":["vat"]}'::jsonb, 'all', '2023-01-01', null, 'NIRC Sec. 114(A), as amended by RA 10963 (TRAIN): quarterly filing within 25 days after the close of the taxable quarter (monthly 2550M no longer required from 1 Jan 2023)', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1601c', '1601C', 'Monthly remittance of tax withheld on compensation', 'monthly', '{"kind":"monthly_following","day":10,"period_months":"all","efps_days":{"A":15,"B":14,"C":13,"D":12,"E":11},"exceptions":[{"period_month":12,"month_offset":1,"day":15}]}'::jsonb, '{"has_employees":true}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 58(A) and 81; RR 2-98 as amended; RR 26-2002 (eFPS staggered filing): 10th day of the following month, December return by 15 January', 'https://www.bir.gov.ph/', null, true, 'eFPS group days (A=15 … E=11) and whether the December 15 January date also applies to eFPS filers to confirm.'),
  ('dl-0619e', '0619E', 'Monthly remittance of creditable (expanded) withholding tax', 'monthly', '{"kind":"monthly_following","day":10,"period_months":"non_quarter_end","efps_days":{"A":15,"B":14,"C":13,"D":12,"E":11}}'::jsonb, '{"withholds_expanded":true}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 58(A); RR 2-98 as amended by RR 11-2018: first two months of each quarter, 10th day of the following month', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1601eq', '1601EQ', 'Quarterly remittance return of creditable (expanded) withholding tax', 'quarterly', '{"kind":"quarterly","quarter_basis":"calendar","quarters":[1,2,3,4],"month_offset":1,"day":"last"}'::jsonb, '{"withholds_expanded":true}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 58(A); RR 2-98 as amended by RR 11-2018: last day of the month following the close of the quarter', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1604c', '1604C', 'Annual information return of income taxes withheld on compensation', 'annual', '{"kind":"annual","year_basis":"calendar","month_offset":1,"day":31}'::jsonb, '{"has_employees":true}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 58(C), as amended by RA 10963 (TRAIN): on or before 31 January of the following year', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1604e', '1604E', 'Annual information return of creditable income taxes withheld (expanded)', 'annual', '{"kind":"annual","year_basis":"calendar","month_offset":3,"day":1}'::jsonb, '{"withholds_expanded":true}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 58(C); RR 2-98 as amended: on or before 1 March of the following year', 'https://www.bir.gov.ph/', null, true, null),
  ('dl-1702q', '1702Q', 'Quarterly income tax return (corporations and partnerships)', 'quarterly', '{"kind":"quarterly","quarter_basis":"taxable_year","quarters":[1,2,3],"days_after":60}'::jsonb, '{"taxpayer_types":["partnership","corporation","opc","cooperative"]}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 77(B): within 60 days after the close of each of the first three quarters of the taxable year', 'https://www.bir.gov.ph/', null, true, 'Filing guide not yet written.'),
  ('dl-1702rt', '1702-RT', 'Annual income tax return (corporations, regular rate)', 'annual', '{"kind":"annual","year_basis":"taxable_year","month_offset":4,"day":15}'::jsonb, '{"taxpayer_types":["partnership","corporation","opc","cooperative"]}'::jsonb, 'all', '2018-01-01', null, 'NIRC Sec. 77(B): on or before the 15th day of the fourth month following the close of the taxable year', 'https://www.bir.gov.ph/', null, true, 'Exempt (1702-EX) and mixed (1702-MX) variants not yet distinguished. Filing guide not yet written.')
